<?php
// Remote reference images are downloaded only from public, pinned addresses.
function aliImageAddress($url){$u=parse_url($url);if(!$u||!in_array($u['scheme']??'',['https','http'],true)||empty($u['host'])||isset($u['user'])||isset($u['pass'])||isset($u['fragment'])||isset($u['port'])&&!in_array($u['port'],[80,443],true))throw new InvalidArgumentException('Usa un enlace público HTTP o HTTPS.');$host=strtolower($u['host']);if(filter_var($host,FILTER_VALIDATE_IP))$ips=[$host];else $ips=gethostbynamel($host)?:[];if(!$ips)throw new InvalidArgumentException('No se pudo resolver el servidor de la imagen.');foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)||strpos($ip,':')!==false)throw new InvalidArgumentException('El enlace no corresponde a un servidor público permitido.');return [$host,$u['port']??($u['scheme']==='https'?443:80),$ips[0]];}
function aliImageDownload($url,$max=5242880){for($i=0;$i<4;$i++){[$host,$port,$ip]=aliImageAddress($url);$body='';$h=curl_init($url);curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>10,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_RESOLVE=>[$host.':'.$port.':'.$ip],CURLOPT_PROXY=>'',CURLOPT_USERAGENT=>'FACTURA.VIP Product Reference/1.0',CURLOPT_WRITEFUNCTION=>function($h,$chunk)use(&$body,$max){if(strlen($body)+strlen($chunk)>$max)return 0;$body.=$chunk;return strlen($chunk);}]);$ok=curl_exec($h);$code=curl_getinfo($h,CURLINFO_HTTP_CODE);$redirect=curl_getinfo($h,CURLINFO_REDIRECT_URL);curl_close($h);if($code>=300&&$code<400&&$redirect){$url=$redirect;continue;}if($ok===false||$code!==200)throw new InvalidArgumentException('No se pudo descargar el recurso. Prueba otra imagen o súbela desde tu equipo.');return $body;}throw new InvalidArgumentException('El recurso tiene demasiadas redirecciones.');}
function aliImageResolve($base,$url){$url=trim(html_entity_decode($url,ENT_QUOTES|ENT_HTML5,'UTF-8'));if(strpos($url,'https://')===0||strpos($url,'http://')===0)return $url;$u=parse_url($base);if(strpos($url,'//')===0)return $u['scheme'].':'.$url;if(strpos($url,'/')===0)return $u['scheme'].'://'.$u['host'].$url;if($url!==''&&!preg_match('~^[a-z]+:~i',$url))return $u['scheme'].'://'.$u['host'].rtrim(dirname($u['path']??'/'),'/').'/'.$url;return '';}
function aliImageCandidates($html,$source,$model){$key=preg_replace('/[^a-z0-9]/','',strtolower($model));$page=preg_replace('/[^a-z0-9]/','',strtolower(strip_tags($html).' '.$source['url'].' '.($source['title']??'')));if($key===''||strpos($page,$key)===false)return [];$dom=new DOMDocument;@$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html,LIBXML_NONET|LIBXML_NOERROR|LIBXML_NOWARNING);$xpath=new DOMXPath($dom);$out=[];foreach($xpath->query('//meta[@property="og:image" or @name="twitter:image" or @property="og:image:secure_url"]') as $node){$url=aliImageResolve($source['url'],$node->getAttribute('content'));if(aliGuideUrl($url))$out[$url]=['url'=>$url,'source'=>$source['url'],'title'=>$source['title']??$model];}if(!$out){$plain=html_entity_decode(str_replace('\\/','/',$html),ENT_QUOTES|ENT_HTML5,'UTF-8');preg_match_all('~https?://[^\s"<>]+?\.(?:png|jpe?g|webp)(?:\?[^\s"<>]*)?~i',$plain,$matches);foreach(array_unique($matches[0]) as $url){$url=rtrim($url,"),; ");if(!aliGuideUrl($url)||preg_match('/(?:logo|worldmap|favicon|banner|sprite|flag|icon)/i',parse_url($url,PHP_URL_PATH)??''))continue;$out[$url]=['url'=>$url,'source'=>$source['url'],'title'=>$source['title']??$model];if(count($out)>=6)break;}}return array_values($out);}
function aliImagesRead($db,$id,$directory){$s=$db->prepare('SELECT Imagen FROM Gen_Producto WHERE IdProducto=? AND Anulado=0');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new InvalidArgumentException('Producto no disponible.');$file=$directory.'/gallery-'.$id.'.json';$extra=is_file($file)?json_decode(file_get_contents($file),true):[];if(!is_array($extra))throw new RuntimeException('Galería inválida');return [$row['Imagen']?:'',$extra[2]??'',$extra[3]??''];}
function aliImageEncode($bytes){$info=@getimagesizefromstring($bytes);if(!$info||!in_array($info['mime'],['image/jpeg','image/png','image/webp'],true)||$info[0]>6000||$info[1]>6000||$info[0]*$info[1]>20000000)throw new InvalidArgumentException('Usa una imagen JPG, PNG o WebP de hasta 5 MB y 20 megapíxeles.');$image=@imagecreatefromstring($bytes);if(!$image)throw new InvalidArgumentException('No se pudo procesar la imagen.');$scale=min(1,1280/max($info[0],$info[1]));$width=max(1,(int)round($info[0]*$scale));$height=max(1,(int)round($info[1]*$scale));$small=imagecreatetruecolor($width,$height);imagealphablending($small,false);imagesavealpha($small,true);$transparent=imagecolorallocatealpha($small,0,0,0,127);imagefill($small,0,0,$transparent);imagecopyresampled($small,$image,0,0,0,0,$width,$height,$info[0],$info[1]);imagedestroy($image);$encoded='';foreach([80,65,50] as $quality){ob_start();$ok=imagewebp($small,null,$quality);$encoded=ob_get_clean();if($ok&&strlen($encoded)<=512000)break;}imagedestroy($small);if(!$ok||strlen($encoded)>1048576)throw new InvalidArgumentException('No se pudo optimizar la imagen a menos de 1 MB. Prueba otra.');return $encoded;}

function aliImageStore($db,$id,$slot,$expected,$bytes,$directory){$encoded=aliImageEncode($bytes);$lock=fopen($directory.'/gallery-'.$id.'.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Galería ocupada');$dest=null;try{$db->beginTransaction();$s=$db->prepare('SELECT Imagen FROM Gen_Producto WHERE IdProducto=? AND Anulado=0 FOR UPDATE');$s->execute([$id]);if(!$s->fetch())throw new InvalidArgumentException('Producto no disponible.');$images=aliImagesRead($db,$id,$directory);if($images[$slot-1]!==$expected)throw new InvalidArgumentException('La galería cambió. Cierra y vuelve a abrir antes de reemplazar una imagen.');$name='product-'.$id.'-'.$slot.'-'.bin2hex(random_bytes(12)).'.webp';$dest=$directory.'/'.$name;if(file_put_contents($dest,$encoded,LOCK_EX)===false)throw new RuntimeException('No se pudo guardar');if($slot===1){$s=$db->prepare('UPDATE Gen_Producto SET Imagen=? WHERE IdProducto=?');$s->execute([$name,$id]);}else{$path=$directory.'/gallery-'.$id.'.json';$extra=is_file($path)?json_decode(file_get_contents($path),true):[];$extra[$slot]=$name;$tmp=tempnam($directory,'gallery-');if(!$tmp||file_put_contents($tmp,json_encode($extra))===false||!rename($tmp,$path))throw new RuntimeException('No se pudo guardar la galería');}$images[$slot-1]=$name;$db->commit();return $images;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($dest&&is_file($dest))unlink($dest);throw $e;}finally{flock($lock,LOCK_UN);fclose($lock);}}
function aliProductImages($db,$q,$r){$p=$q->getParsedBody()?:[];$id=filter_var($p['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)return $r->withJson(['error'=>'Selecciona un producto válido.'],422);$directory=dirname(__DIR__).'/resources/images/productos';try{$product=aliKnowledgeProduct($db,$id);if(!$product)return $r->withJson(['error'=>'Producto no disponible.'],404);$mode=$p['mode']??'';if($mode==='image_gallery')return $r->withJson(['imagenes'=>aliImagesRead($db,$id,$directory)]);if($mode==='image_import'||$mode==='image_upload'){if(!aliKnowledgeCanEdit($db,$q))return $r->withJson(['error'=>'No tienes permiso para guardar imágenes.'],403);$slot=filter_var($p['slot']??null,FILTER_VALIDATE_INT);if(!$slot||$slot<1||$slot>3||($mode==='image_import'&&(!is_string($p['url']??null)||strlen($p['url'])>2000))||!is_string($p['expected']??null)||($p['reviewed']??false)!==true)throw new InvalidArgumentException('Selecciona un espacio del 1 al 3 y confirma la imagen.');if($mode==='image_upload'){if(!is_string($p['data']??null)||strlen($p['data'])>7100000||($bytes=base64_decode($p['data'],true))===false||strlen($bytes)>5242880)throw new InvalidArgumentException('Usa una imagen de hasta 5 MB.');}else $bytes=aliImageDownload($p['url']);return $r->withJson(['imagenes'=>aliImageStore($db,$id,$slot,$p['expected'],$bytes,$directory),'message'=>'Imagen guardada en el producto.']);}
 $model=aliKnowledgeString($p,'exact_model',200,true);$metadata=aliKnowledgeRead($db,$id);$sources=$metadata['sources']??[];if(!$sources){$search=$q->withParsedBody(['id'=>$id,'mode'=>'sales','exact_model'=>$model,'question'=>'Busca páginas del fabricante o distribuidores con fotografías del modelo exacto '.$model.'. Prioriza páginas del producto con imágenes. No inventes enlaces.']);if(aliGuideExactModel($product,$model)===''){$config=aliSettings();if(empty($config['enabled'])||empty($config['key'])||empty($config['web']))return $r->withJson(['error'=>'Puedes subir una imagen desde tu equipo. Activa OpenAI y búsqueda web para buscar referencias.'],409);$payload=aliGuidePayload($product,'Busca páginas con imágenes referenciales del servicio '.$product['Producto'].'. No afirmes un modelo específico.',$config);$data=aliTechnicalModel($payload,$config);}else{$response=aliProductGuide($db,$search,$r);if($response->getStatusCode()!==200)return $response;$data=json_decode((string)$response->getBody(),true);}$sources=$data['sources']??[];}$candidates=[];foreach(array_slice($sources,0,5) as $source){try{$html=aliImageDownload($source['url'],1500000);foreach(aliImageCandidates($html,$source,$model) as $candidate)$candidates[$candidate['url']]=$candidate;}catch(Throwable $e){continue;}}return $r->withJson(['candidates'=>array_slice(array_values($candidates),0,9),'model'=>$model]);
 }catch(InvalidArgumentException $e){return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){return $r->withJson(['error'=>'No se pudieron procesar las imágenes. Intenta nuevamente.'],503);}}
